BEGIN;
CREATE TABLE IF NOT EXISTS finance_task_participants(id BIGSERIAL PRIMARY KEY,ticket_id BIGINT NOT NULL,user_id BIGINT NOT NULL,participant_role VARCHAR(30) NOT NULL CHECK(participant_role IN('assistant','reviewer','collaborator')),can_view BOOLEAN NOT NULL DEFAULT TRUE,can_comment BOOLEAN NOT NULL DEFAULT TRUE,can_edit BOOLEAN NOT NULL DEFAULT FALSE,added_by BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(ticket_id,user_id,participant_role));
CREATE TABLE IF NOT EXISTS finance_task_reviews(id BIGSERIAL PRIMARY KEY,ticket_id BIGINT NOT NULL,submitted_by BIGINT,submitted_at TIMESTAMPTZ,reviewer_user_id BIGINT,review_status VARCHAR(30) NOT NULL DEFAULT 'awaiting_review',rating SMALLINT CHECK(rating BETWEEN 1 AND 5),remarks TEXT,acknowledged_at TIMESTAMPTZ,kpi_related BOOLEAN NOT NULL DEFAULT FALSE,kpi_contribution NUMERIC(8,4),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS finance_task_reminders(id BIGSERIAL PRIMARY KEY,ticket_id BIGINT NOT NULL,user_id BIGINT NOT NULL,reminder_type VARCHAR(30) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,days_before INTEGER,last_sent_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(ticket_id,user_id,reminder_type));
CREATE TABLE IF NOT EXISTS finance_task_communications(id BIGSERIAL PRIMARY KEY,ticket_id BIGINT NOT NULL,comment_id BIGINT,classification VARCHAR(40) NOT NULL,actor_user_id BIGINT NOT NULL,target_user_id BIGINT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
COMMIT;
